// By Astra. Reports are untrusted data, rendered as text only; never executed.
'use strict';
const $=id=>document.getElementById(id), selected=new Set();let report=null;
function element(tag,text,parent){const e=document.createElement(tag);e.textContent=text;parent.append(e);return e;}
function clear(){report=null;selected.clear();$('results').replaceChildren();$('export').disabled=true;$('report').value='';$('status').textContent='No report loaded.';}
$('clear').onclick=clear;
$('report').onchange=async event=>{clearResults();try{const file=event.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Report exceeds 10 MB. Scan a smaller folder.');const r=JSON.parse(await file.text());if(r.schema!=='file-kingdom-name-correction-v1'||typeof r.root!=='string'||!Array.isArray(r.files)||!Array.isArray(r.names)||!Array.isArray(r.skipped)||!Array.isArray(r.errors)||r.files.length>10000)throw Error('Unsupported report.');const ids=new Set();for(const f of r.files){if(typeof f.path!=='string'||typeof f.id!=='string'||ids.has(f.id)||!Array.isArray(f.changes))throw Error('Invalid file entry.');ids.add(f.id);}report=r;$('status').textContent=`${r.files.length} files with old names · ${r.names.length} old file/folder names · ${r.skipped.length} skipped · ${r.errors.length} errors · ${r.complete?'scan finished':'incomplete scan'}`;element('p',r.root,$('results'));for(const f of r.files){const card=element('article','',$('results'));const label=element('label','',card);const box=document.createElement('input');box.type='checkbox';box.disabled=f.editable!==true;label.append(box,document.createTextNode(' '+f.path+(f.editable===true?'':' — manual review')));box.onchange=()=>{box.checked?selected.add(f.id):selected.delete(f.id);$('export').disabled=selected.size===0;};element('small',f.reason||'',card);for(const c of f.changes){element('pre',`Line ${c.line}\nBefore: ${c.before}\nAfter:  ${c.after}`,card);}}for(const [title,rows] of [['Names requiring review',r.names],['Skipped',r.skipped],['Errors',r.errors]]){const d=element('details','',$('results'));element('summary',`${title} (${rows.length})`,d);for(const row of rows)element('p',`${row.path}: ${row.reason||row.action||''}`,d);}}catch(e){clearResults();$('status').textContent='Could not load report: '+e.message;}};
function clearResults(){report=null;selected.clear();$('results').replaceChildren();$('export').disabled=true;}
$('export').onclick=()=>{if(!report||!selected.size)return;const data={schema:'file-kingdom-name-selection-v1',root:report.root,created:new Date().toISOString(),ids:[...selected],files:report.files.filter(f=>selected.has(f.id)).map(({id,path,sha256})=>({id,path,sha256})),note:'Selection only. Review locally before running apply; this file changes nothing.'};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download='name-correction-selection-'+new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Denver'}).format(new Date()).replaceAll('-','')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
